104: 	@Override
105: 	public Obs saveObs(Obs obs, String changeMessage) throws APIException {
106: 		if (obs == null) {
107: 			throw new APIException("Obs.error.cannot.be.null", (Object[]) null);
108: 		}
109: 
110: 		if (obs.getId() != null && changeMessage == null) {
111: 			throw new APIException("Obs.error.ChangeMessage.required", (Object[]) null);
112: 		}
113: 
114: 		ensureRequirePrivilege(obs);
115: 
116: 		//Should allow updating a voided Obs, it seems to be pointless to restrict it,
117: 		//otherwise operations like merge patients won't be possible when to moving voided obs
118: 		if (obs.getObsId() == null || obs.getVoided()) {
119: 			return saveNewOrVoidedObs(obs, changeMessage);
120: 		} else if (!obs.isDirty()) {
121: 			setPersonFromEncounter(obs);
122: 			return saveObsNotDirty(obs, changeMessage);
123: 		} else {
124: 			setPersonFromEncounter(obs);
